create table "public"."sessions" (
    "id" bigint not null,
    "account_id" bigint not null,
    "created_at" timestamp with time zone not null default now(),
    "expires_at" timestamp with time zone not null
);


alter table "public"."sessions" enable row level security;

create table "public"."lobbies" (
    "id" bigint generated by default as identity not null,
    "created_at" timestamp with time zone not null default now(),
    "name" text not null,
    "owner_name" text not null,
    "owner_account_id" bigint not null,
    "is_closed" boolean not null default false,
    "is_muted" boolean not null default false,
    "is_public" boolean not null default true
);


alter table "public"."lobbies" enable row level security;

create table "public"."lobby_members" (
    "id" bigint generated by default as identity not null,
    "created_at" timestamp with time zone not null default now(),
    "lobby_id" bigint not null,
    "account_id" bigint not null,
    "joined_at" timestamp with time zone not null default now()
);


alter table "public"."lobby_members" enable row level security;

create table "public"."lobby_messages" (
    "id" bigint generated by default as identity not null,
    "created_at" timestamp with time zone not null default now(),
    "lobby_id" bigint not null,
    "account_id" bigint not null,
    "message" text not null
);


alter table "public"."lobby_messages" enable row level security;

create table "public"."games" (
    "id" bigint generated by default as identity not null,
    "created_at" timestamp with time zone not null default now(),
    "lobby_id" bigint,
    "owner_account_id" bigint,
    "name" text not null default ''::text,
    "password_protected" boolean not null default false,
    "password" text not null default ''::text,
    "is_locked" boolean not null default false,
    "is_public" boolean not null default false
);


alter table "public"."games" enable row level security;

create table "public"."game_players" (
    "id" bigint generated by default as identity not null,
    "created_at" timestamp with time zone not null default now(),
    "game_id" bigint not null,
    "account_id" bigint not null,
    "joined_at" timestamp with time zone not null default now()
);


alter table "public"."game_players" enable row level security;

CREATE UNIQUE INDEX game_players_game_id_account_id_key ON public.game_players USING btree (game_id, account_id);
CREATE UNIQUE INDEX game_players_pkey ON public.game_players USING btree (id);
CREATE UNIQUE INDEX games_pkey ON public.games USING btree (id);
CREATE UNIQUE INDEX lobbies_pkey ON public.lobbies USING btree (id);
CREATE UNIQUE INDEX lobby_members_lobby_id_account_id_key ON public.lobby_members USING btree (lobby_id, account_id);
CREATE UNIQUE INDEX lobby_members_pkey ON public.lobby_members USING btree (id);
CREATE UNIQUE INDEX lobby_messages_pkey ON public.lobby_messages USING btree (id);
CREATE UNIQUE INDEX sessions_pkey ON public.sessions USING btree (id);

alter table "public"."sessions" add constraint "sessions_pkey" PRIMARY KEY using index "sessions_pkey";
alter table "public"."lobbies" add constraint "lobbies_pkey" PRIMARY KEY using index "lobbies_pkey";
alter table "public"."lobby_members" add constraint "lobby_members_pkey" PRIMARY KEY using index "lobby_members_pkey";
alter table "public"."lobby_messages" add constraint "lobby_messages_pkey" PRIMARY KEY using index "lobby_messages_pkey";
alter table "public"."games" add constraint "games_pkey" PRIMARY KEY using index "games_pkey";
alter table "public"."game_players" add constraint "game_players_pkey" PRIMARY KEY using index "game_players_pkey";

alter table "public"."lobby_members" add constraint "lobby_members_lobby_id_account_id_key" UNIQUE using index "lobby_members_lobby_id_account_id_key";
alter table "public"."game_players" add constraint "game_players_game_id_account_id_key" UNIQUE using index "game_players_game_id_account_id_key";

alter table "public"."sessions" add constraint "sessions_account_id_fkey" FOREIGN KEY (account_id) REFERENCES account(id) ON UPDATE CASCADE ON DELETE CASCADE not valid;
alter table "public"."sessions" validate constraint "sessions_account_id_fkey";

alter table "public"."lobbies" add constraint "lobbies_owner_account_id_fkey" FOREIGN KEY (owner_account_id) REFERENCES account(id) ON UPDATE CASCADE ON DELETE CASCADE not valid;
alter table "public"."lobbies" validate constraint "lobbies_owner_account_id_fkey";

alter table "public"."lobby_members" add constraint "lobby_members_lobby_id_fkey" FOREIGN KEY (lobby_id) REFERENCES lobbies(id) ON UPDATE CASCADE ON DELETE CASCADE not valid;
alter table "public"."lobby_members" validate constraint "lobby_members_lobby_id_fkey";
alter table "public"."lobby_members" add constraint "lobby_members_account_id_fkey" FOREIGN KEY (account_id) REFERENCES account(id) ON UPDATE CASCADE ON DELETE CASCADE not valid;
alter table "public"."lobby_members" validate constraint "lobby_members_account_id_fkey";

alter table "public"."lobby_messages" add constraint "lobby_messages_lobby_id_fkey" FOREIGN KEY (lobby_id) REFERENCES lobbies(id) ON UPDATE CASCADE ON DELETE CASCADE not valid;
alter table "public"."lobby_messages" validate constraint "lobby_messages_lobby_id_fkey";
alter table "public"."lobby_messages" add constraint "lobby_messages_account_id_fkey" FOREIGN KEY (account_id) REFERENCES account(id) ON UPDATE CASCADE ON DELETE CASCADE not valid;
alter table "public"."lobby_messages" validate constraint "lobby_messages_account_id_fkey";

alter table "public"."games" add constraint "games_lobby_id_fkey" FOREIGN KEY (lobby_id) REFERENCES lobbies(id) ON UPDATE CASCADE ON DELETE SET NULL not valid;
alter table "public"."games" validate constraint "games_lobby_id_fkey";
alter table "public"."games" add constraint "games_owner_account_id_fkey" FOREIGN KEY (owner_account_id) REFERENCES account(id) ON UPDATE CASCADE ON DELETE SET NULL not valid;
alter table "public"."games" validate constraint "games_owner_account_id_fkey";

alter table "public"."game_players" add constraint "game_players_game_id_fkey" FOREIGN KEY (game_id) REFERENCES games(id) ON UPDATE CASCADE ON DELETE CASCADE not valid;
alter table "public"."game_players" validate constraint "game_players_game_id_fkey";
alter table "public"."game_players" add constraint "game_players_account_id_fkey" FOREIGN KEY (account_id) REFERENCES account(id) ON UPDATE CASCADE ON DELETE CASCADE not valid;
alter table "public"."game_players" validate constraint "game_players_account_id_fkey";

create or replace view "public"."lobby" as
select
    "lobbies"."id",
    "lobbies"."name",
    "lobbies"."owner_name",
    "lobbies"."owner_account_id",
    "lobbies"."is_closed",
    "lobbies"."is_muted",
    "lobbies"."is_public",
    "lobbies"."created_at"
from "public"."lobbies";

create or replace view "public"."game" as
select
    "games"."id",
    "games"."password_protected",
    "games"."password",
    "games"."name",
    "games"."owner_account_id",
    "games"."lobby_id",
    "games"."is_locked",
    "games"."is_public",
    "games"."created_at"
from "public"."games";

